      "source": "root = Stack([cabin, status, weight, allowance, fee])\n$cabin = 0\n$gold = 0\n$weight = 23\ncabin = Control(\"Cabin\", 0, 1, [\"Economy\", \"Business\"], $cabin)\nstatus = Control(\"Gold status\", 0, 1, [\"No Gold\", \"Gold\"], $gold)\nweight = Control(\"Bag weight (kg)\", 10, 40, [], $weight)\nbase = $cabin == 0 ? 23 : 32\nallowed = base + $gold * 5\nexcess = $weight > allowed ? $weight - allowed : 0\nallowance = Metric(\"Bag allowance (kg)\", allowed)\nfee = Metric(\"Single-bag fee ($)\", excess * 15)",
